  Stage_146248_Name = {
    Text = "Guests at the Feast"
  },
  Stage_146249_Desc = {
    Text = "Seven treasures returned each to its place; seven strands of fate at last converged upon a single end."
  },
  Stage_146249_Name = {
    Text = "Seven Strands of Fate"
  },
  Stage_146250_Desc = {
    Text = "The snowy mountains have but one rule: whatever you hear, do not answer."
  },
  Stage_146250_Name = {
    Text = "Do Not Answer"
  },
  Stage_146251_Desc = {
    Text = [[
The place farthest from the heavens is where poetry and distant longing lie at our very feet.
But do those who hunger for miracles ever raise their eyes to the sky above?]]
  },
  Stage_146251_Name = {
    Text = "The Snowbound"
  },
  Stage_146253_Desc = {
    Text = [[
