  Stage_43506_Desc = {
    Text = [[
Farewell, said the giant.
I shall return to history, where I am invincible and indestructible.
I am immortal.]]
  },
  Stage_43506_Name = {
    Text = "Sunken Horn"
  },
  Stage_43508_Desc = {
    Text = "O forgotten one, where are you heading?\n—To the distant land of solitude. There, the stars and moon are silent, and the ocean is still.\nOnly you and I remain in the world."
  },
