  Stage_58400_Desc = {
    Text = "The Golden City—Isarawu.\nIts wealth is inexhaustible, its desires boundless.\nLike a sponge, it absorbs the endless flow of gold and swells.\nThis is my capital, the queen said. She is proud of it"
  },
  Stage_58400_Name = {
    Text = "Golden City: Part IV"
  },
