  Stage_70092_Desc = {
    Text = "The ovule is a secret prelude.\nNew life has yet to stir, the new seed has yet to take form—miracles are still in gestation."
  },
  Stage_70092_Name = {
    Text = "Ovule's Spark: Murmurs: Madness"
  },
  Stage_70092_StageInitStateText = {Text = "Breeding"},
  Stage_70093_Desc = {
