  },
  Stage_70096_Desc = {
    Text = "The growth rings count the years of the journey.\nCarved into solid, unseen bones by sun and rain, wind and frost, the wet white and the dense black—an inscription of time's passage."
  },
  Stage_70096_Name = {
    Text = "Rings of Growth: Murmurs: Madness"
  },
  Stage_70096_StageInitStateText = {Text = "Breeding"},
