  Stage_70101_StageInitStateText = {Text = "Breeding"},
  Stage_70102_Desc = {
    Text = "Saplings are reckless adventurers.\nSeeds do not know whether the next inch of earth is fertile black soil or cold, barren sand—they simply extend their roots into the ground with fearless determination."
  },
  Stage_70102_Name = {
    Text = "Root's Beginnings: Murmurs: Madness"
  },
  Stage_70102_StageInitStateText = {Text = "Breeding"},
  Stage_70103_Desc = {
