  Stage_70103_Name = {
    Text = "Root's Beginnings: Murmurs Part VI"
  },
  Stage_70104_Desc = {
    Text = [[
Fruit drop is a cruel omen.
The harsher the conditions, the earlier the struggle for survival begins. Death trails close behind, even before new seedlings reach the earth.]]
  },
  Stage_70104_Name = {
    Text = "Fallen Harvest: Murmurs Part VI"
  },
