  },
  Stage_70109_StageInitStateText = {Text = "Breeding"},
  Stage_70110_Desc = {
    Text = "Pollination is a distant encounter.\nThe swaying bough beckons the dancing messenger—inviting it to gather pollen, to linger among the blooms, and in the rhythm of nature, to deliver the source of new life into another awaiting embrace."
  },
  Stage_70110_Name = {
    Text = "Pollen's Dance: Murmurs: Madness"
  },
  Stage_70110_StageInitStateText = {Text = "Breeding"},
