  Stage_7674_Desc = {
    Text = "The crumbling idol beholds its people;\nIt watches them survive, multiply, fight—and in time, forget it entirely.\nThe crumbling idol longs for its people..."
  },
  Stage_7674_Name = {
    Text = "Phantasmal Dive III"
  },
  Stage_7675_Desc = {
    Text = "A seaside town in North Yorkshire—Scarborough. Featuring towering cliffs and golden bays, it is an elegant and charming holiday destination."
  },
  Stage_7675_Name = {
    Text = "Scarborough Summer"
  },
  Stage_7676_Desc = {
    Text = "The crumbling idol beholds its people;\nIt watches them survive, multiply, fight—and in time, forget it entirely.\nThe crumbling idol longs for its people..."
  },
  Stage_7676_Name = {
    Text = "Phantasmal Dive I"
  },
  Stage_7677_Desc = {
    Text = [[
One little mouse, one little mouse.
Run, run! She cut off its tail with a cleaver.]]
  },
  Stage_7677_Name = {
    Text = "Get 'em! Brown!"
  },
  Stage_7678_Desc = {
