  },
  Stage_7747_Name = {
    Text = "Town of Madness I"
  },
  Stage_7748_Desc = {
    Text = "Oh, sewers—conscience of the city, asylum of the city."
  },
  Stage_7748_Name = {Text = "Undercanal"},
  Stage_7749_Desc = {
    Text = "Sure, sure. Eyes are the mind's prison; the soul, the body's shackle."
