  Stage_7825_Name = {
    Text = "Pursuit of Stars"
  },
  Stage_7826_Desc = {
    Text = [[
Rogers Wax Museum sits at the far end of Southwark Street, near a tributary of the Taym.
Unassuming in appearance, yet it draws enthusiasts of avant-garde art from afar.]]
  },
  Stage_7826_Name = {
    Text = "Frenzied Wax Museum I"
  },
  Stage_7827_Desc = {
    Text = [[
