  Stage_7945_Desc = {
    Text = "She is the boundary where dreams and reality intertwine—the reflection dwelling in the depths of every soul that gazes upon the night sky."
  },
  Stage_7945_Name = {
    Text = "Twisted Stars"
  },
  Stage_7945_StageInitStateText = {Text = "Seamare"},
  Stage_7946_Desc = {
    Text = [[
The curved horizon hidden in the depths of the cosmos.
It leads you from one darkness into another.]]
  },
  Stage_7946_Name = {
    Text = "Schwarzschild Throat I"
  },
  Stage_7947_Desc = {
    Text = "The \"Gate\" is about to open, revealing a glimpse of the truth.\nIt's neither black nor white—truth is chromatic yet murky."
  },
  Stage_7947_Name = {
    Text = "Chaos Domain: Fissure III"
  },
  Stage_7948_Desc = {
    Text = [[
