  Stage_7948_Name = {
    Text = "Ruins of Pohnpei V"
  },
  Stage_7949_Desc = {
    Text = [[
It leans against the bedside in docile repose, its dull button eyes fixed upon the void.
The small body has borne all its owner's tears, yet cannot offer a single word of solace.]]
  },
  Stage_7949_Name = {
    Text = "Tears of the Doll II"
  },
  Stage_7950_Desc = {
    Text = "For your health and life, stay away from nicotine."
  },
  Stage_7950_Name = {
    Text = "Smoke and Violet"
  },
  Stage_7951_Desc = {
    Text = [[
