  Stage_8013_Desc = {
    Text = "No one can remove the crown bestowed by the Divine Sovereign, no one."
  },
  Stage_8013_Name = {
    Text = "Lemuria's \"Glory\""
  },
  Stage_8014_Desc = {
    Text = "Friendships that endured the passage of years have borne new hope."
  },
  Stage_8014_Name = {
    Text = "Old Friends, New Friends"
  },
  Stage_8015_Desc = {
    Text = "The night is eroded by undercurrents, and the stars fall silent. The crisis moon, fraught with twists and storms, quietly reflects an unknown future."
  },
  Stage_8015_Name = {
    Text = "Crisis Moon"
  },
  Stage_8016_Desc = {
    Text = "Yes—avarice is his original sin, and he will atone for it."
  },
  Stage_8016_Name = {
    Text = "Annihilation"
  },
  Stage_8017_Desc = {
    Text = "The silent guardian has uttered a new voice."
  },
  Stage_8017_Name = {
    Text = "Overload Safeguard"
  },
  Stage_8018_Desc = {
    Text = "Chasing the alluring light within the endless darkness of night, like a moth drawn to a flame; soaring toward the flames of destiny, heedless of all else."
  },
  Stage_8018_Name = {Text = "Pyre Moth"},
  Stage_8019_Desc = {
    Text = [[
The "Gate" has been opened. The illusion nears its end.
Hush... Do not look. Do not listen.]]
  },
