  Stage_90985_Desc = {
    Text = [[
Let cowards tremble in our path.
All glory is Rome's, and beautiful laurels shall crown the fiercest brow.]]
  },
  Stage_90985_Name = {
    Text = "Champion's Wreath: Part V"
  },
  Stage_90986_Desc = {
    Text = "Cheers and flowers, wine and feasts, gold and treasures—take them all! Laugh from your belly, for this is a warrior's rightful reward."
  },
  Stage_90986_Name = {
    Text = "Triumphant Glory: Part V"
  },
  Stage_90987_Desc = {
